#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "symm.h"


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
      C[i][j] = (DATA_TYPE) ((i+j) % 100) / m;
      B[i][j] = (DATA_TYPE) ((n+i-j) % 100) / m;
    }
  for (i = 0; i < m; i++) {
    for (j = 0; j <= i; j++)
      A[i][j] = (DATA_TYPE) ((i+j) % 100) / m;
    for (j = i+1; j < m; j++)
      A[i][j] = -999; //regions of arrays that should not be used
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /* Use local VLA buffers to improve data locality:
   *  - temp2_row[j] accumulates, for a fixed i, the value that was
   *    previously held in the scalar temp2 for each column j.
   *  - alphaBi[j] caches alpha * B[i][j] so we compute this product
   *    only once per (i,j), preserving the original multiplication
   *    order ( (alpha * B[i][j]) * A[i][k] ).
   *
   * Extra memory is O(n), negligible compared to A/B/C.
   */
  DATA_TYPE temp2_row[n];
  DATA_TYPE alphaBi[n];

#pragma scop
  /* Outer loop over i is kept as in the original code to preserve
   * the update order on C (beta scaling and subsequent accumulations).
   *
   * The main reorganization is:
   *   Original: for i      for j      for k< i
   *   New     : for i      [precompute over j]
   *                         for k< i  for j
   *
   * For each i, we now traverse rows of B and C contiguously in j,
   * which greatly improves cache utilization while keeping the
   * arithmetic and its ordering for each (i,j,k) unchanged.
   */
  for (i = 0; i < _PB_M; i++)
  {
    /* Convenient row pointers for the current i. */
    DATA_TYPE *Ci = C[i];
    DATA_TYPE *Bi = B[i];

    /* Precompute alpha * B[i][j] and initialize the per-column
     * accumulator temp2_row[j] = 0.
     *
     * In the original kernel, temp2 was set to 0 once per (i,j),
     * yielding M*N initializations. Here we also perform M*N
     * initializations in total (one pass over j for each i),
     * so the work is unchanged.
     */
    for (j = 0; j < _PB_N; j++)
    {
      alphaBi[j]   = alpha * Bi[j];   /* (alpha * B[i][j])   */
      temp2_row[j] = (DATA_TYPE)0;    /* temp2 for column j  */
    }

    /* Accumulate the contributions from rows k < i.
     *
     * Original inner structure for a fixed (i,j):
     *   temp2 = 0;
     *   for k = 0..i-1:
     *     C[k][j] += (alpha * B[i][j]) * A[i][k];
     *     temp2   += B[k][j] * A[i][k];
     *
     * Here, for a fixed i, we compute the same operations but with
     * j innermost:
     *
     *   for k = 0..i-1:
     *     for j = 0..n-1:
     *       C[k][j]      += (alpha * B[i][j]) * A[i][k];
     *       temp2_row[j] += B[k][j] * A[i][k];
     *
     * For each fixed (i,j), the sequence of k-iterations and the
     * order in which B[k][j] * A[i][k] is accumulated into the
     * corresponding temp2_row[j] is identical to the original.
     */
    for (k = 0; k < i; k++)
    {
      DATA_TYPE aik = A[i][k];   /* A[i][k] is only used for k < i */
      DATA_TYPE *Ck = C[k];
      DATA_TYPE *Bk = B[k];

      for (j = 0; j < _PB_N; j++)
      {
        /* C[k][j] += (alpha * B[i][j]) * A[i][k]; */
        Ck[j] += alphaBi[j] * aik;

        /* temp2_row[j] += B[k][j] * A[i][k]; */
        temp2_row[j] += Bk[j] * aik;
      }
    }

    /* Diagonal term and beta scaling for row i.
     *
     * Original:
     *   C[i][j] = beta * C[i][j]
     *             + (alpha * B[i][j]) * A[i][i]
     *             + alpha * temp2;
     *
     * We use:
     *   C[i][j] = beta * C[i][j]
     *             + alphaBi[j] * A[i][i]
     *             + alpha * temp2_row[j];
     *
     * which preserves the exact floating-point operation grouping
     * of the original expression.
     */
    {
      DATA_TYPE aii = A[i][i];

      for (j = 0; j < _PB_N; j++)
      {
        Ci[j] = beta * Ci[j]
                + alphaBi[j] * aii
                + alpha * temp2_row[j];
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_symm (m, n,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
