/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  /* Convert the 2D VLAs into 1D restrict pointers to improve
     alias analysis and enable better vectorization.  The layout
     is still row-major: element (i,j) is at base[i*dim + j]. */
  DATA_TYPE *restrict Cdata = &C[0][0];
  DATA_TYPE *restrict Adata = &A[0][0];
  DATA_TYPE *restrict Bdata = &B[0][0];

  const int m_dim = m; /* leading dimension of A (m x m)          */
  const int n_dim = n; /* leading dimension of B and C (m x n)    */

  /* Tunable column block size. We block and parallelize over
     column blocks (jb) to:
       - preserve the original (i,j) execution order for each column,
       - keep good spatial locality in the innermost j-loop,
       - expose coarse-grain parallelism across independent columns. */
  const int J_BLOCK = 32;

  /* BLAS PARAMS
     SIDE = 'L'
     UPLO = 'L'
     =>  Form  C := alpha*A*B + beta*C
     A is MxM
     B is MxN
     C is MxN
     note that due to Fortran array layout, the code below more closely
     resembles upper triangular case in BLAS
  */

#pragma scop
  /* Parallelize over column blocks. Each block of columns is handled
     by exactly one thread, so there are no races on C. */
#pragma omp parallel for schedule(static)
  for (int jb = 0; jb < _PB_N; jb += J_BLOCK)
  {
    int j_end = jb + J_BLOCK;
    if (j_end > _PB_N)
      j_end = _PB_N;

    /* Outer loop over rows of A, B, C. Execution order in i is the
       same as in the original kernel. */
    for (int i = 0; i < _PB_M; ++i)
    {
      /* Precompute row offsets for A (m_dim) and B/C (n_dim). */
      const int a_row_offset = i * m_dim;  /* A[i][0] index in Adata    */
      const int bc_row_offset = i * n_dim; /* B[i][0], C[i][0] indices  */

      /* Pointer to the beginning of row i of A. */
      const DATA_TYPE *restrict Arow = &Adata[a_row_offset];

      /* Loop over the current block of columns. For each column j we
         compute exactly the same operations as in the original code,
         in the same (i,k) order for a fixed j. */
      for (int j = jb; j < j_end; ++j)
      {
        /* temp2 is the same accumulation variable as in the original
           code: temp2 = sum_{k=0}^{i-1} B[k][j] * A[i][k]. */
        DATA_TYPE temp2 = 0;

        /* B[i][j] reused multiple times; precompute alpha * B[i][j]. */
        const int cij_index = bc_row_offset + j; /* index of C[i][j] and B[i][j] */
        const DATA_TYPE Bij = Bdata[cij_index];
        const DATA_TYPE alphaBij = alpha * Bij;

        /* Indices for walking down column j of C and B.  We update/
           read elements (k,j) for k = 0..i-1 using explicit strides
           of n_dim to match row-major storage. */
        int Ckj_index = j; /* C[0][j] */
        int Bkj_index = j; /* B[0][j] */

        /* Inner product over k (0 .. i-1).
           Original loop body:
             C[k][j] += alpha * B[i][j] * A[i][k];
             temp2   +=        B[k][j] * A[i][k];

           We keep the same iteration order in k. The loop is safe to
           vectorize: each iteration touches distinct C[k][j] and the
           only loop-carried dependence is the scalar reduction temp2. */
#pragma omp simd reduction(+:temp2)
        for (int k = 0; k < i; ++k)
        {
          const DATA_TYPE Aik = Arow[k];          /* A[i][k] */

          Cdata[Ckj_index] += alphaBij * Aik;     /* C[k][j] update */
          temp2            += Bdata[Bkj_index] * Aik;

          Ckj_index += n_dim; /* advance by one row (k+1,j) */
          Bkj_index += n_dim;
        }

        /* Final update of C[i][j]:
             C[i][j] = beta * C[i][j]
                        + alpha * B[i][j] * A[i][i]
                        + alpha * temp2;
           We reuse alphaBij and A[i][i] from Arow. */
        const DATA_TYPE Aii = Arow[i];            /* A[i][i] */

        Cdata[cij_index] =
          beta  * Cdata[cij_index] +
          alphaBij * Aii +
          alpha * temp2;
      } /* end for j */
    }   /* end for i */
  }     /* end for jb */
#pragma endscop
}


int main(int argc, char** argv)
