/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimized version:
 *  - Reorders loops from (i,j,k) to (column blocks jb, i, k, j) while
 *    preserving the exact per-element operation order.
 *  - Uses a temporary buffer temp2[j] per (i, column block) to
 *    compute all temp2(i,j) values for a block of columns at once.
 *    This is mathematically equivalent to the original scalar temp2,
 *    but greatly improves spatial locality and enables vectorization
 *    in the innermost j-loop.
 *  - Applies blocking in the column (N) dimension to keep active data
 *    in cache and to provide a coarse-grain parallel loop.
 *  - Adds OpenMP parallelization across independent column blocks.
 *    Each block owns a disjoint set of columns, so there are no data
 *    races on C, and the sequential dependence along the i-dimension
 *    for each column is preserved.
 *  - Introduces local restrict-qualified aliases for A, B, C to help
 *    the compiler optimize and vectorize memory accesses.
 */
static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  /* Local restrict-qualified aliases to help the optimizer.
   *
   * In PolyBench, A, B, and C are allocated as disjoint arrays,
   * so it is safe to promise non-aliasing here and only access
   * them through these aliases inside this kernel.
   */
  DATA_TYPE (*restrict C_)[n] = C;
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE (*restrict B_)[n] = B;

  const int Mdim = _PB_M;
  const int Ndim = _PB_N;

  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

  int i, j, k;

  /* Original BLAS-like operation:
   *   C := alpha * A * B + beta * C
   * where A is lower-triangular (SYM) and SIDE='L', UPLO='L'.
   *
   * Original code (for reference):
   *
   *   for (i = 0; i < _PB_M; i++)
   *     for (j = 0; j < _PB_N; j++) {
   *       temp2 = 0;
   *       for (k = 0; k < i; k++) {
   *         C[k][j] += alpha * B[i][j] * A[i][k];
   *         temp2   += B[k][j] * A[i][k];
   *       }
   *       C[i][j] = beta * C[i][j] +
   *                 alpha * B[i][j] * A[i][i] +
   *                 alpha * temp2;
   *     }
   *
   * Below we implement an equivalent computation but with a
   * loop structure more amenable to cache reuse and SIMD.
   */

#pragma scop
  /* Parallelize over column blocks. Each block handles a disjoint
   * set of columns [jb, j_end) for all rows i, so there are no
   * dependences between different jb-iterations.
   *
   * When OpenMP is disabled, this pragma is ignored and the code
   * runs sequentially with the same semantics.
   */
#pragma omp parallel for schedule(static) private(i,j,k)
  for (int jb = 0; jb < Ndim; jb += T_BLOCK_J)
  {
    /* Determine column range for this block. */
    const int j_end      = (jb + T_BLOCK_J < Ndim) ? (jb + T_BLOCK_J) : Ndim;
    const int block_size = j_end - jb;

    /* Temporary accumulation buffer:
     *   temp2_block[jj] stores, for current (i, jb-block),
     *   temp2(i, j) = sum_{k < i} B[k][j] * A[i][k]
     * for j = jb + jj.
     *
     * This exactly matches the original scalar temp2 per (i,j),
     * but is computed for the entire column block at once.
     */
    DATA_TYPE temp2_block[T_BLOCK_J];

    /* Loop over rows of A/B/C. The order in i is preserved for
     * each column j, which is required because:
     *  - row i of C is read only at iteration i (for that row),
     *    before any later iterations i' > i update C[i][*],
     *  - rows k < i of C are incrementally updated at all later
     *    iterations i' > k.
     */
    for (i = 0; i < Mdim; ++i)
    {
      /* Initialize temp2 for this (i, column block). */
      for (int jj = 0; jj < block_size; ++jj)
        temp2_block[jj] = (DATA_TYPE)0;

      /* Accumulate contributions from rows k < i.
       *
       * For each k < i:
       *   - update C[k][j]   += alpha * B[i][j] * A[i][k]
       *   - accumulate temp2 +=        B[k][j] * A[i][k]
       *
       * This is a direct reordering of the original inner loop:
       * we keep the order in k, but for each k we process all
       * columns in the current jb-block (j = jb..j_end-1) at once.
       */
      for (k = 0; k < i; ++k)
      {
        const DATA_TYPE a_ik        = A_[i][k];
        const DATA_TYPE alpha_a_ik  = alpha_local * a_ik;

        /* Row pointers for the current column block. */
        DATA_TYPE *restrict Ck = &C_[k][jb];
        DATA_TYPE *restrict Bi = &B_[i][jb];
        DATA_TYPE *restrict Bk = &B_[k][jb];

        /* Inner-most loop over the block of columns.
         * All three arrays (Ck, Bi, Bk) are accessed with
         * unit stride, enabling efficient SIMD vectorization.
         */
#pragma GCC ivdep
        for (int jj = 0; jj < block_size; ++jj)
        {
          Ck[jj]         += alpha_a_ik * Bi[jj];
          temp2_block[jj] += Bk[jj] * a_ik;
        }
      }

      /* Final update for row i in this column block:
       *
       *   C[i][j] = beta*C[i][j]
       *             + alpha*B[i][j]*A[i][i]
       *             + alpha*temp2(i,j)
       */
      const DATA_TYPE a_ii        = A_[i][i];
      const DATA_TYPE alpha_a_ii  = alpha_local * a_ii;

      DATA_TYPE *restrict Ci = &C_[i][jb];
      DATA_TYPE *restrict Bi = &B_[i][jb];

#pragma GCC ivdep
      for (int jj = 0; jj < block_size; ++jj)
      {
        const DATA_TYPE c_old = Ci[jj];
        /* Mathematically identical to the original expression.
         * The order of operations affecting each C[i][j] and
         * temp2(i,j) remains the same as in the original code,
         * so floating-point round-off behavior is preserved.
         */
        Ci[jj] = beta_local * c_old
               + alpha_a_ii * Bi[jj]
               + alpha_local * temp2_block[jj];
      }
    } /* end loop over i */
  } /* end loop over jb */
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_symm (m, n,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

