/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  // BLAS PARAMS
  // SIDE = 'L'
  // UPLO = 'L'
  // =>  Form  C := alpha*A*B + beta*C
  // A is MxM
  // B is MxN
  // C is MxN
  // note that due to Fortran array layout, the code below more closely
  // resembles upper triangular case in BLAS
#pragma scop
  /* Parallelize along the j-dimension for each fixed i.
   *
   * Dependencies:
   *  - For a given (k,j), C[k][j] is updated for all i > k.
   *    Therefore, the loop over i must remain logically sequential.
   *  - For fixed i, different columns j are independent, so we can
   *    safely distribute the j-loop across threads.
   *
   * We create a single parallel region so that the OpenMP team is
   * reused for all iterations of i, avoiding repeated thread
   * creation/destruction. When compiled without OpenMP support, all
   * OpenMP pragmas are ignored and the code reduces to a sequential
   * implementation with the same computation order as the original.
   */
#pragma omp parallel private(i,j,k)
  {
    for (i = 0; i < _PB_M; i++)
    {
      /* Access row i of A via a local pointer to help the compiler
       * keep it in registers and improve cache locality.
       * This variable has automatic storage inside the parallel
       * region and is therefore thread-private.
       */
      DATA_TYPE* Ai = A[i];
      const DATA_TYPE Aii = Ai[i];

      /* Distribute the inner j-loop across threads.
       * The implicit barrier at the end of this omp for ensures that
       * for a given i, all updates to C[*,*] complete before any
       * thread proceeds to the next value of i. This preserves the
       * original sequential dependence structure along i.
       */
#pragma omp for schedule(static)
      for (j = 0; j < _PB_N; j++)
      {
        /* Per-(i,j) accumulator, as in the original code.  It must
         * be private to each (i,j) instance, which is naturally
         * ensured by declaring it inside the j-loop.
         */
        DATA_TYPE temp2 = 0;

        /* Hoist invariant values out of the k-loop.  In the original
         * kernel, alpha and B[i][j] are constant over k.
         */
        const DATA_TYPE Bij       = B[i][j];
        const DATA_TYPE alpha_bij = alpha * Bij;

        /* Inner loop over k:
         *
         * Original form:
         *   for (k = 0; k < i; k++) {
         *     C[k][j] += alpha * B[i][j] * A[i][k];
         *     temp2   += B[k][j] * A[i][k];
         *   }
         *
         * Here we:
         *   - reuse the row pointer Ai (Ai[k] == A[i][k]),
         *   - reuse the precomputed alpha_bij,
         *   - keep the loop bounds and iteration order identical
         *     (0 .. i-1), preserving per-element update order, and
         *   - encourage vectorization of the k-loop with omp simd.
         */
#if defined(_OPENMP)
#pragma omp simd reduction(+:temp2)
#endif
        for (k = 0; k < i; k++)
        {
          DATA_TYPE Aik = Ai[k];
          C[k][j] += alpha_bij * Aik;
          temp2   += B[k][j] * Aik;
        }

