         * This expression is algebraically identical to the original:
         *
         *   C[i][j] = beta * C[i][j]
         *             + alpha * B[i][j] * A[i][i]
         *             + alpha * temp2;
         *
         * but it reuses alpha_bij and Aii to reduce redundant loads
         * and multiplications.
         */
        C[i][j] = beta * C[i][j] + alpha_bij * Aii + alpha * temp2;
      } /* end j-loop (parallelized) */
    }   /* end i-loop (sequential across iterations) */
  }     /* end parallel region */
#pragma endscop
